function solveNQueens(n) {
  const solutions = [];
  const queenInRow = [];              // queenInRow[r] = the column used

  const usedCols  = new Set();
  const usedDown  = new Set();        // row - col
  const usedUp    = new Set();        // row + col

  function place(row) {
    if (row === n) {
      solutions.push([...queenInRow]);
      return;
    }

    for (let col = 0; col < n; col++) {
      const down = row - col, up = row + col;
      if (usedCols.has(col) || usedDown.has(down) || usedUp.has(up)) continue;

      usedCols.add(col); usedDown.add(down); usedUp.add(up);
      queenInRow.push(col);

      place(row + 1);

      queenInRow.pop();
      usedCols.delete(col); usedDown.delete(down); usedUp.delete(up);
    }
  }

  place(0);
  return solutions;
}
